from pybricks.hubs import PrimeHub
from pybricks.parameters import Button, Direction, Port, Stop
from pybricks.pupdevices import ColorSensor, ForceSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

# Set up all devices.
prime_hub_ = PrimeHub()
color_sensor = ColorSensor(Port.E)
Touch_Sensor = ForceSensor(Port.F)
Left = Motor(Port.A, Direction.COUNTERCLOCKWISE)
Right = Motor(Port.B, Direction.CLOCKWISE)
drive_base = DriveBase(Left, Right, 66, 150)
MM_Left = Motor(Port.C, Direction.CLOCKWISE)
MM_Right = Motor(Port.D, Direction.CLOCKWISE)

# Initialize variables.
myWhite = 100
myBlack = 0
targetValue = 50
baseSpeed = 200
turnAmount = 10
run_number = 0
max_runs = 8
running = 0
targetAngle = 0
currentAngle = 0
error = 0
correction = 0
Kp = 2
distance = 0

async def Run_1():
    await wait(0)
    # Haeun's Mission
    drive_base.reset(0, 0)
    await DriveStraight(630, 470)
    await drive_base.straight(-60)
    await drive_base.turn(-16)
    await drive_base.straight(-90)
    await drive_base.turn(10)
    drive_base.settings(straight_acceleration=750)
    drive_base.settings(straight_speed=600)
    await drive_base.straight(-500, then=Stop.COAST)
    drive_base.stop()

async def Run_2():
    await wait(0)
    # Haeun's Mission
    drive_base.reset(0, 0)
    drive_base.settings(straight_acceleration=750)
    drive_base.settings(straight_speed=280)
    await drive_base.straight(220)
    drive_base.settings(straight_speed=400)
    await drive_base.straight(-300, then=Stop.COAST)
    drive_base.stop()

async def Run_5():
    await wait(0)
    # Aadhya's Run
    drive_base.reset(0, 0)
    await DriveStraight(800, 500)
    await drive_base.turn(43)
    await DriveStraight(85.5, 300)
    # Wack the gears out
    await multitask(
        MM_Left.run_angle(600, -80),
        MM_Right.run_angle(600, -80),
    )
    await multitask(
        MM_Left.run_angle(600, 60),
        MM_Right.run_angle(600, 60),
    )
    await multitask(
        MM_Left.run_angle(600, -40),
        MM_Right.run_angle(600, -40),
    )
    await multitask(
        MM_Left.run_angle(1000, 60),
        MM_Right.run_angle(1000, 60),
    )
    await multitask(
        MM_Left.run_angle(1000, -60),
        MM_Right.run_angle(1000, -60),
    )
    await multitask(
        MM_Left.run_angle(1000, 60),
        MM_Right.run_angle(1000, 60),
    )
    await drive_base.turn(8)
    # Move backwards to loot
    await drive_base.straight(-800)
    await DriveStraight(100, 400)
    # Turn towards hide the artifacts
    await drive_base.turn(80)
    await drive_base.straight(-340)
    await drive_base.turn(40)
    # Go to home
    await drive_base.turn(-95)
    await drive_base.straight(-700)
    await drive_base.turn(-70)
    await drive_base.straight(-1000, then=Stop.COAST)
    drive_base.stop()

async def Run_6():
    await wait(0)
    # Describe your program.
    drive_base.reset(0, 0)
    await drive_base.straight(410)
    # Start lift 2 below straight not above
    await MM_Right.run_angle(300, 140)
    # Wait for cart to cross the arch
    await wait(1000)
    await MM_Right.run_angle(400, -140)
    # Move back and turn towards the relic to replace
    drive_base.settings(straight_speed=500)
    await drive_base.straight(-115)
    await drive_base.turn(-20)
    await drive_base.straight(130)
    await drive_base.turn(-52)
    await drive_base.straight(393)
    # Turn twords the pedestal
    await drive_base.turn(84)
    await drive_base.straight(18)
    # dROPPING THE RELIC
    await MM_Left.run_angle(100, -40)
    # Go back to home base
    drive_base.settings(straight_acceleration=750)
    drive_base.settings(straight_speed=800)
    await drive_base.straight(-60)
    await drive_base.turn(-70)
    await drive_base.straight(-300)
    await drive_base.turn(40)
    await drive_base.straight(-350, then=Stop.COAST)
    drive_base.stop()

async def Run_3():
    await wait(0)
    # Kaylene's Mission
    drive_base.reset(0, 0)
    await DriveStraight(660, 300)
    drive_base.settings(turn_rate=80)
    await drive_base.turn(-90)
    drive_base.settings(straight_speed=120)
    await drive_base.straight(210)
    await drive_base.straight(-100)
    drive_base.settings(turn_rate=250)
    await drive_base.turn(-90)
    await DriveStraight(800, 800)
    drive_base.stop()

async def Run_4():
    await wait(0)
    # Vivian's Mission
    drive_base.reset(0, 0)
    drive_base.settings(straight_acceleration=500)
    drive_base.settings(straight_speed=500)
    await drive_base.straight(760)
    print(drive_base.angle())
    # motor dip 1st
    await drive_base.turn(15)
    await MM_Left.run_angle(190, 20)
    await drive_base.straight(40)
    await MM_Left.run_angle(190, 40)
    # Go Back!
    await drive_base.straight(-50)
    drive_base.settings(straight_speed=800)
    await drive_base.turn(-20)
    await drive_base.straight(-900)
    drive_base.stop()

async def DriveStraight(dist, speed):
    global targetAngle, baseSpeed, currentAngle, error, correction
    await wait(0)
    drive_base.use_gyro(True)
    drive_base.reset(0, 0)
    targetAngle = 0
    drive_base.settings(straight_acceleration=400)
    baseSpeed = speed
    while not drive_base.distance() >= dist:
        await wait(0)
        currentAngle = drive_base.angle()
        error = targetAngle - currentAngle
        correction = Kp * error
        drive_base.drive(baseSpeed, correction)
    drive_base.straight(0)

async def Run_7():
    await wait(0)
    print('Hello, Pybricks!')
    # Im using the gyro so it can be perfectly straight and not be in an angel.
    drive_base.use_gyro(True)
    drive_base.settings(turn_rate=100)
    await DriveStraight(252.5, 500)
    # Turn 90 degrees towards the mission model
    await drive_base.turn(-90)
    await DriveStraight(220, 500)
    await DriveStraight(80, 300)
    # Pick the LegoLith
    await MM_Left.run_angle(100, -96)
    await drive_base.straight(-250, then=Stop.NONE)
    # Turn to face bridge the gap
    await drive_base.turn(32)
    await DriveStraight(690, 480)
    await wait(0)
    await drive_base.turn(40)
    await drive_base.turn(-40)
    drive_base.settings(straight_speed=800)
    drive_base.settings(turn_rate=500)
    await drive_base.straight(-720, then=Stop.NONE)
    await drive_base.turn(40, then=Stop.NONE)
    await drive_base.straight(-330, then=Stop.COAST)
    drive_base.stop()

async def Run_8():
    await wait(0)
    # Vivian Coded - Emmy to Run
    drive_base.reset(0, 0)
    await DriveStraight(750, 500)
    await drive_base.turn(-100)
    print(drive_base.angle())
    await DriveStraight(150, 330)
    drive_base.settings(straight_speed=500)
    await drive_base.straight(-130)
    await drive_base.turn(-35)
    await drive_base.straight(-120)
    await drive_base.turn(100)
    # then turn and come back!
    await drive_base.turn(-30)
    await DriveStraight(80, 400)
    await drive_base.turn(90)
    await DriveStraight(750, 700)
    drive_base.stop()

async def main():
    global run_number, max_runs, running
    # Mission Selector Program
    # Overriding Center Button from stopping a program when running.
    prime_hub_.system.set_stop_button(Button.BLUETOOTH)
    run_number = 1
    max_runs = 8
    running = 1
    prime_hub_.display.off()
    # Hub display turned off. Waiting for Mission Selection
    # Main program runs forever until Center Button is pressed
    while running:
        await wait(0)
        # Scroll LEFT for mission selection
        if Button.LEFT in prime_hub_.buttons.pressed():
            # Wait until button is released
            while Button.LEFT in prime_hub_.buttons.pressed():
                await wait(0)
            run_number = run_number - 1
            if run_number < 1:
                run_number = max_runs
                await wait(200)
            print('Mission:', run_number, sep=", ")
            prime_hub_.display.number(run_number)
        # Scroll RIGHT for mission selection
        if Button.RIGHT in prime_hub_.buttons.pressed():
            while Button.RIGHT in prime_hub_.buttons.pressed():
                await wait(0)
            run_number = run_number + 1
            if run_number > max_runs:
                run_number = 1
                await wait(200)
            print('Mission:', run_number, sep=", ")
            prime_hub_.display.number(run_number)
        # Center Button for selecting and running missions
        if Button.CENTER in prime_hub_.buttons.pressed():
            while Button.CENTER in prime_hub_.buttons.pressed():
                await wait(0)
            print('Touch Button Released')
            # Showing mission number once again. Display should be showing it already
            prime_hub_.display.number(run_number)
            if run_number == 1:
                print('Calling Mission 1')
                await Run_1()
            elif run_number == 2:
                await Run_2()
            elif run_number == 3:
                await Run_3()
            elif run_number == 4:
                await Run_4()
            elif run_number == 5:
                await Run_5()
            elif run_number == 6:
                await Run_6()
            elif run_number == 7:
                await Run_7()
            elif run_number == 8:
                await Run_8()
            else:
                # Do Nothing
                pass
        # End of Program


run_task(main())